from collections import Counter
def minWindow(s, t):
    need = Counter(t)
    for L in range(len(t), len(s) + 1):
        for i in range(len(s) - L + 1):
            w = Counter(s[i:i + L])
            if all(w[c] >= n for c, n in need.items()):
                return s[i:i + L]
    return ""

